#!/usr/bin/env python3
"""Finite numerical consistency checks for the Euclidean-distance weighted Bergman kernel."""
import cmath
import math


def coefficient(t, n):
    return math.gamma(2 * n + t + 3) / (2 * math.pi * math.gamma(2 * n + 2) * math.gamma(t + 1))


def exact_kernel(t, s):
    if s == 0:
        return (t + 1) * (t + 2) / (2 * math.pi)
    x = cmath.sqrt(s)
    a = t + 2
    return (t + 1) * ((1 - x) ** (-a) - (1 + x) ** (-a)) / (4 * math.pi * x)


def series_kernel(t, s, cutoff=100):
    # Coefficients generated by exact adjacent Gamma ratios, avoiding overflow.
    c = (t + 1) * (t + 2) / (2 * math.pi)
    total = 0j
    power = 1 + 0j
    for n in range(cutoff):
        total += c * power
        power *= s
        c *= (2 * n + t + 3) * (2 * n + t + 4) / ((2 * n + 2) * (2 * n + 3))
    return total


def predicted_zeros(t):
    a = t + 2
    return [-math.tan(math.pi * k / a) ** 2 for k in range(1, 100) if 4 * k < a]


def run():
    for t in (-0.5, 0, 1, 2, 3, 6, 7, 11):
        for s in (-0.35, -0.1, 0, 0.1, 0.45):
            a = exact_kernel(t, s)
            b = series_kernel(t, s, 110)
            assert abs(a - b) < 1e-8 * max(1, abs(a)), (t, s, a, b)
        roots = predicted_zeros(t)
        assert len(roots) == math.ceil((t + 2) / 4) - 1
        for s in roots:
            assert -1 < s < 0
            assert abs(exact_kernel(t, s)) < 1e-9, (t, s)
    assert len(predicted_zeros(2)) == 0
    assert len(predicted_zeros(2.001)) == 1
    assert len(predicted_zeros(6)) == 1
    assert len(predicted_zeros(6.001)) == 2
    print('Finite arithmetic checks passed; analytic proof establishes the universal theorem.')


if __name__ == '__main__':
    run()
